mapper.select:
SELECT DISTINCT COUNT(DISTINCT T1.SRV_CNSRQ_ID) OVER() AS TOT_CNT,
/* isry.itgcm.linkmng.outsd.mapper.LinkMohwSrvcRqstMapper.selectMohwSrvcRqstRcptList*/ T1.SRV_RQST_LINK_DCD AS SRV_RQST_LINK_DCD /* 서비스의뢰연계구분코드*/ , T1.SRV_RQST_APLY_DCD AS SRV_RQST_APLY_DCD /* 서비스의뢰신청구분코드*/ , T1.SRV_RQST_APLY_TCD AS SRV_RQST_APLY_TCD /* 서비스의뢰신청유형코드*/ , T1.SRV_CNSRQ_ID AS SRV_CNSRQ_ID /* 서비스상담의뢰ID*/ , T1.RQST_INST_TYP_DTL_CD AS RQST_INST_TYP_DTL_CD /* 의뢰기관유형상세코드*/ , T1.RQST_INST_TYP_DTL_NM AS RQST_INST_TYP_DTL_NM /* 의뢰기관유형상세명*/ , T1.RQST_SRV_INST_ID AS RQST_SRV_INST_ID /* 의뢰서비스기관ID*/ , (SELECT X.UNT_TASKWK_SE_CD FROM SAA000 X WHERE X.INST_NO = T1.RQST_PRCS_SRV_INST_ID) AS UNT_TASKWK_SE_CD /* 의뢰서비스기관*/ , T1.RQST_SRV_INST_NM AS RQST_SRV_INST_NM /* 의뢰서비스기관명*/ , T1.DSCSN_YMD AS DSCSN_YMD /* 상담일자*/ , T1.RQST_YMD AS RQST_YMD /* 의뢰일자*/ , T1.RQST_INST_PIC_FLNM AS RQST_INST_PIC_FLNM /* 의뢰기관담당자성명*/ , T1.RQST_INST_PIC_TELNO AS RQST_INST_PIC_TELNO /* 의뢰기관담당자전화번호*/ , T1.RQST_INST_PIC_MPNO AS RQST_INST_PIC_MPNO /* 의뢰기관담당자휴대전화번호*/ , T1.CLNT_DSCSN_OPIN_CN AS CLNT_DSCSN_OPIN_CN /* 의뢰인상담소견내용*/ , T1.RQST_INST_PIC_SPCL_CN AS RQST_INST_PIC_SPCL_CN /* 의뢰기관담당자특화내용*/ , T1.RQST_INST_PIC_NTCE_USE_YN AS RQST_INST_PIC_NTCE_USE_YN /* 의뢰기관담당자알림사용여부*/ , T1.TRPR_FLNM AS TRPR_FLNM /* 대상자성명*/ , T1.TRPR_RRNO AS TRPR_RRNO /* 대상자주민등록번호*/ , T1.TRPR_RRNO_ENCPT AS TRPR_RRNO_ENCPT /* 대상자주민등록번호암호화*/ , T1.TRPR_BRDT AS TRPR_BRDT /* 대상자생년월일*/ , T1.TRPR_RRNO_SEX_CD AS TRPR_RRNO_SEX_CD /* 대상자주민등록번호성별코드*/ , T1.TRPR_MGEMD_DEPT_CD AS TRPR_MGEMD_DEPT_CD /* 대상자관리읍면동부서코드*/ , T1.TRPR_TELNO AS TRPR_TELNO /* 대상자전화번호*/ , T1.TRPR_MPNO AS TRPR_MPNO /* 대상자휴대전화번호*/ , T1.TRPR_RDNM_ZIP AS TRPR_RDNM_ZIP /* 대상자도로명우편번호*/ , T1.TRPR_RDNMADR AS TRPR_RDNMADR /* 대상자도로명주소*/ , T1.TRPR_RDNM_DTLADR AS TRPR_RDNM_DTLADR /* 대상자도로명상세주소*/ , T1.HOPE_SPRT_CD_LST AS HOPE_SPRT_CD_LST /* 희망지원코드목록*/ , T1.HOPE_SPRT_ETC_CN AS HOPE_SPRT_ETC_CN /* 희망지원기타내용*/ , T1.TRPR_PRVC_PVAGR_YN AS TRPR_PRVC_PVAGR_YN /* 대상자개인정보제공동의여부*/ , T1.TRPR_OVL_DSDGR_CD AS TRPR_OVL_DSDGR_CD /* 대상자종합장애정도코드*/ , T1.PRCS_RQST_INST_TYP_DTL_CD AS PRCS_RQST_INST_TYP_DTL_CD /* 처리의뢰기관유형상세코드*/ , T1.RQST_PRCS_SRV_INST_ID AS RQST_PRCS_SRV_INST_ID /* 의뢰처리서비스기관ID*/ , T1.RQST_PRCS_SRV_INST_NM AS RQST_PRCS_SRV_INST_NM /* 의뢰처리서비스기관명*/ , T1.RQST_SRC_INST_RSC_PRVSV_ID AS RQST_SRC_INST_RSC_PRVSV_ID /* 의뢰원천기관자원제공서비스ID*/ , T1.RQST_RSC_PRVSV_NM AS RQST_RSC_PRVSV_NM /* 의뢰자원제공서비스명*/ , T1.RQST_APLY_SRV_BGNG_YMD AS RQST_APLY_SRV_BGNG_YMD /* 의뢰신청서비스시작일자*/ , T1.RQST_APLY_SRV_END_YMD AS RQST_APLY_SRV_END_YMD /* 의뢰신청서비스종료일자*/ , T1.RQST_ATCFL_NM AS RQST_ATCFL_NM /* 의뢰첨부파일명*/ , T1.ESB_TX_ID AS ESB_TX_ID /* 연계트랜젝션아이디*/ , T1.ESB_SEQ AS ESB_SEQ /* 연계시퀸스*/ , T1.ESB_IF_ID AS ESB_IF_ID /* 연계인터페이스ID*/ , T1.SND_CD AS SND_CD /* 송신기관코드*/ , T1.RCV_CD AS RCV_CD /* 수신기관코드*/ , T1.ESB_FILE_NAME AS ESB_FILE_NAME /* 연계파일이름*/ , T1.CREATE_TIME AS CREATE_TIME /* 데이터생성일시*/ , T1.ESB_INIT_TIME AS ESB_INIT_TIME /* 연계시작일시*/ , T1.ESB_COMPLITE_TIME AS ESB_COMPLITE_TIME /* 연계종료일시*/ , T1.ESB_STATUS AS ESB_STATUS /* 연계상태*/ , (SELECT aa.SRV_RQST_PRCS_DCD FROM (SELECT T2.SRV_RQST_PRCS_DCD FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa WHERE rownum = 1) AS CAB110_SRV_RQST_PRCS_DCD , (SELECT aa.ESB_STATUS FROM (SELECT T2.ESB_STATUS FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa WHERE rownum = 1) AS CAB110_ESB_STATUS , (SELECT aa.SRV_RQST_PRCS_ID FROM (SELECT T2.SRV_RQST_PRCS_ID FROM CAB110 T2 WHERE T2.SRV_CNSRQ_ID = T1.SRV_CNSRQ_ID ORDER BY t2.CREATE_TIME desc) aa WHERE rownum = 1) AS SRV_RQST_PRCS_ID
FROM CAB100 T1 /* 복지부 서비스의뢰접수*/ WHERE 1 = 1 AND T1.RQST_YMD BETWEEN #{RQST_START_YMD} /* 의뢰시작일자*/ AND #{RQST_END_YMD} /* 의뢰종료일자*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND T1.TRPR_FLNM = #{TRPR_FLNM} /* 대상자명*/
AND T1.RQST_SRV_INST_NM LIKE '%'|| #{RQST_SRV_INST_NM} ||'%' /* 의뢰서비스기관명*/
AND T1.RQST_INST_PIC_FLNM = #{RQST_INST_PIC_FLNM} /* 의뢰기관담당자성명*/
AND T1.SRV_RQST_APLY_TCD = #{SRV_RQST_APLY_TCD} /* 의뢰신청유형*/
AND EXISTS ( SELECT 'X' FROM SAA000 X /* 기관*/ WHERE X.INST_NO = T1.RQST_PRCS_SRV_INST_ID /* 의뢰원천기관자원제공서비스ID*/ AND X.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 의뢰신청유형기관단위업무구분코드*/ UNION ALL SELECT 'X' FROM SDA600 F /* 순수자원제공주체*/ WHERE F.INST_NO = T1.RQST_PRCS_SRV_INST_ID AND F.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} )
/*2023.09.04 운영팀 정현진 학교밖 요청사항 정렬순서변경 요청)*/ ORDER BY RQST_YMD DESC
